# Applies the round-12 repair edits to push/OBSTRUCTION_MAP.md (text only; every patch matches once). As first run it placed the regular-representation row after S12 with id S13; apply_map2.py moved it to section 3.3 as Q28, and this file now shows the corrected placement.
import os, json
HERE = os.path.dirname(os.path.abspath(__file__))
MAP = os.path.join(HERE, '..', 'OBSTRUCTION_MAP.md')
t = open(MAP, encoding='utf-8').read()
log = []
def rep(old, new, tag):
    global t
    assert t.count(old) == 1, (tag, t.count(old))
    t = t.replace(old, new); log.append(tag)
def after_row(prefix, row, tag):
    global t
    lines = t.split('\n')
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, (tag, idx)
    lines.insert(idx[0] + 1, row); t = '\n'.join(lines); log.append(tag)

